package pe.cruzroja.convocatorias.users.domain; import java.util.UUID; public class VolunteerProfile {private final UUID userId; private final String document; private String phone,address,availability; private TrainingLevel level; public VolunteerProfile(UUID userId,String document,String phone,String address,String availability,TrainingLevel level){if(userId==null||document==null||document.isBlank()||level==null)throw new IllegalArgumentException("Perfil inválido");this.userId=userId;this.document=document;this.phone=phone;this.address=address;this.availability=availability;this.level=level;} public void promoteTo(TrainingLevel next){if(next==null||next.ordinal()<level.ordinal())throw new IllegalArgumentException("El nivel de formación solo puede subir");level=next;} public TrainingLevel level(){return level;} public UUID userId(){return userId;} public String document(){return document;} public String phone(){return phone;} public String address(){return address;} public String availability(){return availability;} }
